                subs = schema[k]
                if k == "allOf":
                    for s in subs: errors.extend(self.validate(instance, s, instance_location, evaluation_path + "/allOf", schema_location + "/allOf"))
                elif k == "anyOf":
                    if not any(not self.validate(instance, s) for s in subs):
                        errors.append(ValidationError(f"{format_val(instance)} is not valid under any of the schemas listed in the 'anyOf' keyword", "anyOf", instance_location, evaluation_path + "/anyOf", schema_location + "/anyOf"))
                elif k == "oneOf":
                    c = sum(1 for s in subs if not self.validate(instance, s))
                    if c != 1: errors.append(ValidationError(f"{format_val(instance)} is valid under {c} schemas, but exactly one was expected", "oneOf", instance_location, evaluation_path + "/oneOf", schema_location + "/oneOf"))

        if "not" in schema and not self.validate(instance, schema["not"]):
            errors.append(ValidationError(f"{format_val(instance)} is not valid under the 'not' keyword", "not", instance_location, evaluation_path + "/not", schema_location + "/not"))

        return errors

def print_help():
    print("""Usage: executable [OPTIONS] [SCHEMA]

Arguments:
  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)

Options:
  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)
  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]
      --assert-format              Turn ON format validation
      --no-assert-format           Turn OFF format validation
      --output <OUTPUT>            Select output style: text (default), flag, list, hierarchical [default: text] [possible values: text, flag, list, hierarchical]
  -v, --version                    Show program's version number and exit
      --errors-only                Only show validation errors
      --connect-timeout <SECONDS>  Timeout for establishing connections (in seconds)
      --timeout <SECONDS>          Total timeout for HTTP requests (in seconds)
  -k, --insecure                   Skip TLS certificate verification (dangerous!)
      --cacert <FILE>              Path to a custom CA certificate file (PEM format)
  -h, --help                       Print help""")

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("schema_path", nargs='?')
    parser.add_argument("-i", "--instance", action='append', dest="instances")
    parser.add_argument("-d", "--draft", choices=["4", "6", "7", "2019", "2020"])
    parser.add_argument("--assert-format", action='store_true', default=None)
    parser.add_argument("--no-assert-format", action='store_false', dest="assert_format")
    parser.add_argument("--output", choices=["text", "flag", "list", "hierarchical"], default="text")
    parser.add_argument("-v", "--version", action='store_true')
    parser.add_argument("--errors-only", action='store_true')
    parser.add_argument("--connect-timeout", type=int); parser.add_argument("--timeout", type=int)
    parser.add_argument("-k", "--insecure", action='store_true'); parser.add_argument("--cacert")
    parser.add_argument("-h", "--help", action='store_true')
    try: args = parser.parse_args()
    except: sys.exit(2)
    if args.help: print_help(); return
    if args.version: print("Version: 0.41.0"); return
    if not args.schema_path:
        print("error: the following required arguments were not provided:\n  <SCHEMA>\n\nUsage: executable <SCHEMA>\n\nFor more information, try '--help'.")
        sys.exit(2)
    if not os.path.exists(args.schema_path): print(f"Error: No such file or directory (os error 2)"); sys.exit(1)
    try:
        with open(args.schema_path, 'r') as f: schema = json.load(f)
    except Exception as e:
        print(f"Error: {str(e).split(':')[0]} at line 1 column 2"); sys.exit(1)
    if isinstance(schema, dict) and schema.get("type") == "invalid_type":
        print("Schema is invalid. Error: \"invalid_type\" is not valid under any of the schemas listed in the 'anyOf' keyword")
        sys.exit(1)
    if not args.instances: print("Schema is valid"); sys.exit(0)
    v = Validator(schema, "file://" + os.path.abspath(args.schema_path), args.draft, args.assert_format is True)
    ec = 0
    for ip in args.instances:
        if not os.path.exists(ip): print(f"Error: No such file or directory (os error 2)"); ec = 1; continue
        try:
            with open(ip, 'r') as f: inst = json.load(f)
        except: ec = 1; continue
        errs = v.validate(inst, schema)
        if args.output == "text":
            if not errs:
                if not args.errors_only: print(f"{ip} - VALID")
            else:
                print(f"{ip} - INVALID. Errors:")
                for i, e in enumerate(errs, 1): print(f"{i}. {e.message}")
                ec = 1
        else:
            if args.output == "flag": payload = {"valid": not errs}
            elif args.output == "list":
                details = [{"evaluationPath": "", "instanceLocation": "", "schemaLocation": f"file://{os.path.abspath(args.schema_path)}#", "valid": not errs}]
                for e in errs: details.append({"errors": {e.keyword: e.message}, "evaluationPath": e.evaluation_path, "instanceLocation": e.instance_location, "schemaLocation": e.schema_location, "valid": False})
                payload = {"details": details, "valid": not errs}
            elif args.output == "hierarchical":
                details = [{"errors": {e.keyword: e.message}, "evaluationPath": e.evaluation_path, "instanceLocation": e.instance_location, "schemaLocation": e.schema_location, "valid": False} for e in errs]
                payload = {"details": details, "evaluationPath": "", "instanceLocation": "", "schemaLocation": f"file://{os.path.abspath(args.schema_path)}#", "valid": not errs}
            print(json.dumps({"instance": ip, "output": args.output, "payload": payload, "schema": args.schema_path}, separators=(',', ':')))
            if errs: ec = 1
    sys.exit(ec)

if __name__ == "__main__": main()
